    at Generator.next (<anonymous>)
    at /path/node_modules/@swc/core/index.js:18:71
    at new Promise (<anonymous>) {
  code: 'StringExpected'
}
```

### Input code

```typescript
// test.js
const swc = require('@swc/core');
const Visitor = require('@swc/core/Visitor').default;

swc.transformFile('./foo.js', {
  plugin: m => new class extends Visitor {
    visitIdentifier(node) {
      console.log(node);
      return node;
    }
  }().visitProgram(m),
});

// foo.js
console.log('Hello, world!');
```


